window.addEventListener('focus',refreshUpdates);

async function billingRequest(action,features){
 const r=await fetch('/api/easytime/business-billing'+(workspace?'?workspace='+encodeURIComponent(workspace):''),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,features,catalogVersion:planCatalog.version})});const x=await r.json();if(!r.ok)throw Error(x.error||'Could not update the feature quote.');return x;
}
async function loadPlanPricing(){const requestedWorkspace=workspace;
 try{const r=await fetch('/api/easytime/business-billing'+(workspace?'?workspace='+encodeURIComponent(workspace):''),{cache:'no-store'});const x=await r.json();if(!r.ok)throw Error(x.error||'Pricing could not load.');if(workspace!==requestedWorkspace||demo)return;planCatalog=x.catalog;planQuote=x.quote;planBillingStatus=x.billingStatus;if(page==='Plans'&&!document.querySelector('#feature-plan-form :focus'))render();}
 catch{if(workspace===requestedWorkspace&&!demo){planCatalog=publicCatalog(pricingCatalog('',false));planQuote=null;planBillingStatus='Pricing is unavailable. No payment has been taken.';if(page==='Plans'&&!document.querySelector('#feature-plan-form :focus'))render();}}
}
function makePlanUI(){return businessPlanUI({db,access,esc,panel,catalog:planCatalog,quote:planQuote,billingStatus:planBillingStatus,
 refreshQuote:async features=>{const quote=demo?quoteFeatures(pricingCatalog('',false),features):(await billingRequest('quote',features)).quote;planQuote=quote;return quote;},
 saveSelection:features=>save('wf:selectFeatures',{features}),
 checkout:features=>{if(demo)throw Error('Payments are disabled in sample mode.');return billingRequest('checkout',features);}
 });}

function makeSpendUI(){return spendUI({db,access,esc,btn,input,select,modal,save,table,panel,opts,money,workspace,demo,downloadSpend:(format,filters)=>downloadSpendReport(format,db,filters)});}
